    try {
      const saved = await firstValueFrom(this.http.post<Person>(url, null, this.session.headers()));
      if (this.session.sheet() === sheet) {
        this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
        void this.read(sheet);
      }
